const response = $json || {};
let input = {};
let prepared = {};
try {
  input = $node['Workflow Input'].json || {};
} catch (error) {
  input = {};
}
try {
  prepared = $node['Remove Config From Item'].json || {};
} catch (error) {
  prepared = {};
}
const data = ((response.body || {}).data) || {};
const conversation = data.conversation || {};
const contact = data.contact || {};
const conversationId = String(
  data.conversationId ||
  data.conversation_id ||
  conversation.id ||
  response.conversationId ||
  input.conversationId ||
  input.conversation_id ||
  ''
).trim();
return [{
  json: {
    ...input,
    ...prepared,
    conversationId,
    conversation_id: conversationId,
    contactId: contact.id || conversation.contact_id || input.contactId || input.contact_id || null,
    correlationId: prepared.correlationId || prepared.correlation_id || input.correlationId || input.correlation_id || '',
    memorySeed: {
      contact,
      conversation,
      sourceWorkflow: response.body?.meta?.workflow || '',
      statusCode: response.statusCode || null,
    },
    conversationResolved: Boolean(conversationId),
  },
}];

return $input.all().map((item) => {
  const json = { ...(item.json || {}) };
  const contextData = ((json.body || {}).data) || {};
  let input = {};
  let resolved = {};
  let recentData = {};
  let summaryData = {};
  try {
    input = $node['Workflow Input'].json || {};
  } catch (error) {
    input = {};
  }
  try {
    resolved = $node['Resolve Conversation Identity'].json || {};
  } catch (error) {
    resolved = {};
  }
  try {
    recentData = ((($node['Load Recent Messages'].json || {}).body || {}).data) || {};
  } catch (error) {
    recentData = {};
  }
  try {
    summaryData = ((($node['Load Conversation Summary'].json || {}).body || {}).data) || {};
  } catch (error) {
    summaryData = {};
  }
  const conversation = contextData.conversation || resolved.memorySeed?.conversation || {};
  const summaryRecord = contextData.summary || summaryData.summary || {};
  const conversationId = String(
    resolved.conversationId ||
    contextData.conversationId ||
    contextData.conversation_id ||
    conversation.id ||
    input.conversationId ||
    input.conversation_id ||
    ''
  ).trim();
  const correlationId = resolved.correlationId || json.correlationId || json.correlation_id || input.correlationId || input.correlation_id || '';
  const memory = {
    customerId: conversation.customer_id || conversation.contact_id || resolved.customerId || input.customerId || null,
    conversationId: conversationId || null,
    currentOrderId: conversation.current_order_id || input.currentOrderId || null,
    currentPickupId: conversation.current_pickup_id || input.currentPickupId || null,
    currentDeliveryId: conversation.current_delivery_id || input.currentDeliveryId || null,
    currentComplaintId: conversation.current_complaint_id || input.currentComplaintId || null,
    branchId: conversation.branch_id || input.branchId || null,
    language: conversation.language || summaryRecord.language || input.detectedLanguage || input.language || null,
    currentIntent: conversation.intent || conversation.current_intent || input.intent || null,
    humanHandoffStatus: conversation.human_handoff_status || null,
    summary: summaryRecord.summary || contextData.summaryText || '',
    recentMessages: Array.isArray(recentData.messages) ? recentData.messages : [],
  };

  return {
    ...item,
    json: {
      ...input,
      ...resolved,
      ...json,
      memory,
      conversationId,
      conversation_id: conversationId,
      correlationId,
      success: true,
      status: 'SUCCESS',
    },
  };
});

const configKeys = ["SERVICE_API_BASE_URL","N8N_API_KEY","WHATSAPP_PHONE_NUMBER_ID","WHATSAPP_ACCESS_TOKEN","WHATSAPP_AUDIO_MAX_BYTES","OPENAI_CHAT_MODEL","OPENAI_TRANSCRIPTION_MODEL","OPERATIONS_ALERT_PHONE","CONVERSATION_SUMMARY_MESSAGE_THRESHOLD","N8N_RETRY_MAX_ATTEMPTS","N8N_RETRY_BASE_MS","N8N_RETRY_MAX_BACKOFF_MS","N8N_WF_IDEMPOTENCY_CHECK_ID","N8N_WF_PHONE_NORMALIZATION_ID","N8N_WF_CUSTOMER_IDENTITY_ID","N8N_WF_MEMORY_MANAGER_ID","N8N_WF_AI_AGENT_ID","N8N_WF_ORDER_TRACKING_ID","N8N_WF_PICKUP_REQUEST_ID","N8N_WF_AREA_BRANCH_RESOLVER_ID","N8N_WF_DRIVER_DISPATCH_ID","N8N_WF_DRIVER_NOTIFICATION_ID","N8N_WF_DRIVER_REASSIGNMENT_ID","N8N_WF_COMPLAINT_ID","N8N_WF_NOTIFY_BRANCH_MANAGER_ID","N8N_WF_HUMAN_HANDOFF_ID","N8N_WF_VOICE_PROCESSING_ID","N8N_WF_RESPONSE_SENDER_ID","N8N_WF_SAVE_SUMMARY_ID","N8N_WF_ERROR_HANDLER_ID","N8N_WF_RETRY_QUEUE_ID"];
return $input.all().map((item) => {
  const json = { ...(item.json || {}) };
  const serviceApiBaseUrl = String(json.SERVICE_API_BASE_URL || 'MISSING_SERVICE_API_BASE_URL').replace(/\/$/, '').replace(/\/api\/v1$/i, '');
  const apiToken = String(json.N8N_API_KEY || '');
  const identityCustomer = ((json.identity || {}).customer) || {};
  const normalizedMessage = json.normalizedMessage || {};
  const customerId = json.customerId || ((json.customer || {}).id) || identityCustomer.id || '';
  const normalizedPhone = json.normalizedPhone || json.normalized_phone || json.customerPhone || json.customer_phone || (json.identity || {}).normalizedPhone || '';
  const correlationId = json.correlationId || json.correlation_id || '';
  const sourceMessageId = json.wamid || json.messageId || normalizedMessage.wamid || null;
  json.serviceApiBaseUrl = serviceApiBaseUrl;
  json.apiToken = apiToken;
  json.activeConversationUrl = serviceApiBaseUrl + '/api/v1/ai/conversations/active?customerId=' + encodeURIComponent(customerId) + '&phone=' + encodeURIComponent(normalizedPhone);
  json.createConversationUrl = serviceApiBaseUrl + '/api/v1/ai/conversations';
  json.createConversationBody = {
    provider: 'whatsapp',
    customerId: customerId || null,
    normalizedPhone: normalizedPhone || null,
    language: json.language || json.detectedLanguage || null,
    correlationId,
    sourceMessageId,
  };
  for (const key of configKeys) delete json[key];
  return { ...item, json };
});
